INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2005, 'Política Internacional', NULL, 'Item 1 (TPS 2005) — consulte o caderno original', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2005, 'Português', 'Interpretação de texto', 'Item 2 (TPS 2005): Relações Exteriores Ministério das Relações Exteriores UM PAIS DE TODOS GOVERNO FEDERAL Admissão à Carreira de Diplomata LEIA COM ATENÇÃO AS INSTRUÇÕES ABAIXO. Ao receber este cademo, confira se ele contém cinquenta questões, corretamente ordenadas de 1 a 50. | Você encontrará dois tipos de questões objetivas: múltipla escolha e CERTO ou ERRADO. Nas questões do tipo múltipla escolha, marque, em cada uma, a única opção correta (A, B, C, D ou E), de acordo com o respectivo comando. Nas questões do tipo CERTO ou ERRADO, com quatro itens cada uma, marque, para cada item: o campo designado com o código C, caso julgue o item CERTO, ou o campo designado com o código E, caso julgue o item ERRADO.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2005, 'Português', 'Macroeconomia', 'Item 3 (TPS 2005): Relações Exteriores Ministério das Relações Exteriores UM PAIS DE TODOS GOVERNO FEDERAL Admissão à Carreira de Diplomata LEIA COM ATENÇÃO AS INSTRUÇÕES ABAIXO. Ao receber este cademo, confira se ele contém cinquenta questões, corretamente ordenadas de 1 a 50. | Caso o cademo esteja incompleto ou tenha qualquer defeito, solicite ao fiscal de sala mais próximo que tome as providências cabíveis.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2005, 'Política Internacional', NULL, 'Item 4 (TPS 2005) — consulte o caderno original', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2005, 'Português', 'Interpretação de texto', 'Item 5 (TPS 2005): Relações Exteriores Ministério das Relações Exteriores UM PAIS DE TODOS GOVERNO FEDERAL Admissão à Carreira de Diplomata LEIA COM ATENÇÃO AS INSTRUÇÕES ABAIXO. Ao receber este cademo, confira se ele contém cinquenta questões, corretamente ordenadas de 1 a 50. Nas questões objetivas, recomenda-se não marcar ao acaso: em cada questão do tipo múltipla escolha e em cada item de questão do tipo CERTO o | Nas questões discursivas, os espaços para rascunho deste caderno são de uso opcional; não contarão, portanto, para efeito de avaliação. 6 No caderno de respostas das questões discursivas, não será avaliado texto escrito a lápis, texto escrito em local indevido ou texto que tenha identificação fora do local apropriado. 8 Não utilize nenhum material de consulta que não seja fornecido pelo CESPE. discursivas e deixe o local do teste. caderno de respostas das questões discursivas poderá implicar a anulação do seu teste. AGENDA 1', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
